-- Polestar.NewQuests: which quests Forever added (in no Classic quest data),
-- and the "New in Forever" mark beside their names: a small, quiet ∞ on guide
-- steps, "While you're here" rows, the Codex's quest pages and the quest
-- lines of tooltips (ui.newInForever turns it off).
--
-- The ids are NewQuestIds.lua's (generated by `forge data newquests`): one
-- string of fixed-width decimal ids, ascending, searched in place. A set of
-- ~1,800 table keys would cost ~70 KB resident; the string costs its length.

local ADDON, ns = ...

local N = {}
ns.NewQuests = N

local L = ns.L

local byte, gsub, floor, format = string.byte, string.gsub, math.floor, string.format

ns.RegisterDefaults("ui", {
	newInForever = true, -- the ∞ "New in Forever" mark beside quests Forever added
})

local ids, width, count = "", 6, 0

-- From NewQuestIds.lua: w digits an id, line breaks ignored.
function N.Register(w, text)
	if type(w) ~= "number" or w < 1 or type(text) ~= "string" then return end
	text = gsub(text, "%s+", "")
	if #text % w ~= 0 then return end
	ids, width, count = text, w, #text / w
end

-- The id at position i (1-based) of the string, read from its bytes: no
-- string is made per lookup.
local function at(i)
	local p, v = (i - 1) * width, 0
	for k = p + 1, p + width do v = v * 10 + byte(ids, k) - 48 end
	return v
end

-- Whether Forever added quest `id`.
function N.IsNew(id)
	id = tonumber(id)
	if not id or count == 0 then return false end
	local lo, hi = 1, count
	while lo <= hi do
		local mid = floor((lo + hi) / 2)
		local v = at(mid)
		if v == id then return true end
		if v < id then lo = mid + 1 else hi = mid - 1 end
	end
	return false
end

-- How many ids are held (tests, the memory budget).
function N.Count() return count end

function N.Shown()
	return ns.Get("ui.newInForever") ~= false
end

-- The ∞ mark as an inline texture: Media/UI/icon-forever (tools/media/ui.js
-- `forever`, muted gold in its own colours, not tinted), 16x8, a little under
-- the cap height of the guide's and the tooltips' text.
local GLYPH = format("|T%s:8:16:0:0|t", "Interface\\AddOns\\" .. ADDON .. "\\Media\\UI\\icon-forever")
function N.Glyph()
	return GLYPH
end

-- " <glyph>" to put after quest `id`'s name, or "" (an old quest, or the mark
-- turned off).
function N.Mark(id)
	if not N.Shown() or not N.IsNew(id) then return "" end
	return " " .. N.Glyph()
end

-- The words a tooltip about quest `id` adds under its name, or nil.
function N.TooltipText(id)
	if not N.Shown() or not N.IsNew(id) then return nil end
	return N.Glyph() .. " " .. L["New in Forever"]
end
